WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_121'), 'Regression test added with the outbox:

for crash of [none, "beforeCommit", "afterCommit", "afterPublish", "beforeMarkSent"]:
  for brokerDown of [false, true]:
    enroll(u1), enroll(u2) with the crash and the broker state
    restart the service; broker up; run the relay until no row is pending
    assert: each committed enrollment has exactly 1 distinct enrollment.created id
    assert: no enrollment.created exists for an enrollment that did not commit

Statement: "This test fails on the code from evidence D (at least for afterCommit and for the broker-down runs) and passes on the outbox version in every combination, which is the evidence that the dual write is gone."', 'single_choice'::question_type, 'True. On the code from D, a crash after COMMIT or a broker outage leaves a committed enrollment with no event, so the first assertion fails; that reproduces the incident deterministically, which a log line never can. On the outbox version every combination ends with one distinct id per committed enrollment: crashes before COMMIT leave neither row, crashes after COMMIT leave a pending row the relay sends after the restart, and a crash after a publish leads to a re-publish with the same id. A test that fails on the old code and passes on the new one is the proof a fix needs; "no warnings since the deploy" only shows that no failover has happened yet.', 6, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_121') AND order_index = 6)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_dce_122 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dce_122', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-1-2' AND is_deleted = false LIMIT 1), 'commit-succeeded-publish-failed', 'DB Commit Succeeded, Publish Failed', 'During a three-minute broker failover, 37 CodeDev learners were enrolled (their rows are committed and they got 201 Created) but the certificate service never received enrollment.created for them: no welcome email, no badge. A crash between the commit and the publish loses events the same way. The enrollment service commits the enrollment, then publishes, and swallows the publish error.

Fix createEnrollmentService so that every committed enrollment eventually produces exactly one logical enrollment.created, and no event exists for an enrollment that did not commit, whatever the broker and the process do:
- enroll(cmd) keeps its validation (409 "unknown course", "already enrolled"), writes the enrollment AND an outbox row { id: ids.next("evt"), aggregateType: "enrollment", aggregateId: <enrollment id>, eventType: "enrollment.created", payload: { enrollmentId, userId, courseId }, createdAt, status: "pending", sentAt: null } in the same db.tx(), and does not publish. Enrolling must work while the broker is down.
- relayOnce() (the scheduler calls it every second) publishes every pending outbox row, in the order the rows were written, to the "enrollments" topic as { id: <outbox id>, key: <aggregateId>, type: <eventType>, payload }, and marks a row "sent" (with sentAt) only after its publish returned. If a publish throws, leave the remaining rows pending for the next tick.
The certificate service deduplicates by message id: a row published twice with the same id counts once, a row published under two different ids counts twice.

The file provides db.tx(fn) (runs fn on a copy of the tables and commits only if fn returns), broker.publish (throws BrokerTimeout while the broker is down), ids.next(prefix) (a sequence), clock.now() and the crash points. Do not change them or the test runner.

Input (stdin, JSON): { courses: [{ id, title, seats }], steps }. A step is { op: "enroll", userId, courseId, crash? }, { op: "relay", crash? } or { op: "broker", up: boolean }. crash is "beforeCommit", "afterCommit" or "afterPublish": the process dies the first time it reaches that point during the step (every later call in that step throws Crash, even if a catch swallowed the first one), and the runner restarts the service, which loses everything held in memory.
Output: one line per enroll step with the answer ("201 Created", "409 rejected (<reason>)", "500 ..." or "no response (process crashed <point>)"), then, after a final restart with the broker up and three relay ticks, one line per committed enrollment "<userId>/<courseId>: <n> event(s)" (deduplicated by message id), the number of events that belong to no committed enrollment, and the number of outbox rows still pending. Expected: 1 event for every enrollment, 0 orphan events, 0 pending rows.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 1, 'After the COMMIT of enroll(), where does the information "this enrollment still needs its event" live? What happens to it when the broker is down for three minutes, or when the process is killed and restarted?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 2, 'Look at the two places that touch the broker: the try/catch after db.tx() in enroll(), and relayOnce(), which does nothing today. The first must disappear from the request path; the second is where publishing belongs. In the relay, check which id goes on the wire and when a row stops being pending.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 3, 'A similar case on different data: a wallet top-up writes { topup } and, in the same tx, a row { id: ids.next("msg"), kind: "wallet.credited", status: "queued" }. A worker later reads the queued rows in order, sends each one with its own row id as the message id, and only then flips it to "done" in a second tx. If the worker dies between the send and the flip, the same message id is sent again and the receiver ignores it.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
