VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 'Broker failover during enroll: every committed enrollment still gets its event', '{"courses":[{"id":"c1","title":"PostgreSQL Performance Engineering","seats":500},{"id":"c2","title":"API Design for Production","seats":500}],"steps":[{"op":"enroll","userId":"u1","courseId":"c1"},{"op":"broker","up":false},{"op":"enroll","userId":"u2","courseId":"c1"},{"op":"enroll","userId":"u3","courseId":"c1"},{"op":"broker","up":true},{"op":"enroll","userId":"u4","courseId":"c1"},{"op":"relay"}]}', '"enroll u1/c1: 201 Created\nenroll u2/c1: 201 Created\nenroll u3/c1: 201 Created\nenroll u4/c1: 201 Created\n--- after a restart and 3 relay ticks with the broker up\nu1/c1: 1 event\nu2/c1: 1 event\nu3/c1: 1 event\nu4/c1: 1 event\nevents for no committed enrollment: 0\noutbox rows still pending: 0"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 'Process crashes right after COMMIT: the event goes out after the restart', '{"courses":[{"id":"c1","title":"PostgreSQL Performance Engineering","seats":500},{"id":"c2","title":"API Design for Production","seats":500}],"steps":[{"op":"enroll","userId":"u1","courseId":"c1","crash":"afterCommit"},{"op":"enroll","userId":"u2","courseId":"c1"},{"op":"relay"}]}', '"enroll u1/c1: no response (process crashed afterCommit)\nenroll u2/c1: 201 Created\n--- after a restart and 3 relay ticks with the broker up\nu1/c1: 1 event\nu2/c1: 1 event\nevents for no committed enrollment: 0\noutbox rows still pending: 0"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 'Crash before COMMIT: no enrollment and no event, the retried request works', '{"courses":[{"id":"c1","title":"PostgreSQL Performance Engineering","seats":500},{"id":"c2","title":"API Design for Production","seats":500}],"steps":[{"op":"enroll","userId":"u1","courseId":"c1","crash":"beforeCommit"},{"op":"enroll","userId":"u1","courseId":"c1"},{"op":"enroll","userId":"u2","courseId":"c2","crash":"beforeCommit"},{"op":"relay"}]}', '"enroll u1/c1: no response (process crashed beforeCommit)\nenroll u1/c1: 201 Created\nenroll u2/c2: no response (process crashed beforeCommit)\n--- after a restart and 3 relay ticks with the broker up\nu1/c1: 1 event\nevents for no committed enrollment: 0\noutbox rows still pending: 0"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 'Relay crashes after a publish: the row is sent again with the same id and counts once', '{"courses":[{"id":"c1","title":"PostgreSQL Performance Engineering","seats":500},{"id":"c2","title":"API Design for Production","seats":500}],"steps":[{"op":"enroll","userId":"u1","courseId":"c1"},{"op":"enroll","userId":"u2","courseId":"c1"},{"op":"relay","crash":"afterPublish"},{"op":"enroll","userId":"u3","courseId":"c1"},{"op":"relay","crash":"afterPublish"},{"op":"relay"}]}', '"enroll u1/c1: 201 Created\nenroll u2/c1: 201 Created\nenroll u3/c1: 201 Created\n--- after a restart and 3 relay ticks with the broker up\nu1/c1: 1 event\nu2/c1: 1 event\nu3/c1: 1 event\nevents for no committed enrollment: 0\noutbox rows still pending: 0"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 'Broker down while the relay runs: rows stay pending and are published later', '{"courses":[{"id":"c1","title":"PostgreSQL Performance Engineering","seats":500},{"id":"c2","title":"API Design for Production","seats":500}],"steps":[{"op":"enroll","userId":"u1","courseId":"c1"},{"op":"enroll","userId":"u2","courseId":"c1"},{"op":"broker","up":false},{"op":"relay"},{"op":"enroll","userId":"u3","courseId":"c1"},{"op":"relay","crash":"afterCommit"},{"op":"relay"}]}', '"enroll u1/c1: 201 Created\nenroll u2/c1: 201 Created\nenroll u3/c1: 201 Created\n--- after a restart and 3 relay ticks with the broker up\nu1/c1: 1 event\nu2/c1: 1 event\nu3/c1: 1 event\nevents for no committed enrollment: 0\noutbox rows still pending: 0"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_122'), 'Rejected commands (already enrolled, unknown course) produce no event', '{"courses":[{"id":"c1","title":"PostgreSQL Performance Engineering","seats":500},{"id":"c2","title":"API Design for Production","seats":500}],"steps":[{"op":"enroll","userId":"u1","courseId":"c1"},{"op":"enroll","userId":"u1","courseId":"c1"},{"op":"enroll","userId":"u2","courseId":"c9"},{"op":"broker","up":false},{"op":"enroll","userId":"u1","courseId":"c1"},{"op":"enroll","userId":"u3","courseId":"c2"},{"op":"broker","up":true},{"op":"relay"}]}', '"enroll u1/c1: 201 Created\nenroll u1/c1: 409 rejected (already enrolled)\nenroll u2/c9: 409 rejected (unknown course)\nenroll u1/c1: 409 rejected (already enrolled)\nenroll u3/c2: 201 Created\n--- after a restart and 3 relay ticks with the broker up\nu1/c1: 1 event\nu3/c2: 1 event\nevents for no committed enrollment: 0\noutbox rows still pending: 0"', 2, false, true, 6),
