-- challenge chal_quiz_dce_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dce_131', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-1-3' AND is_deleted = false LIMIT 1), 'outbox-same-transaction', 'Outbox in the same transaction', 'Two pieces of code from CodeDev services that write outbox rows. Decide whether each statement about what PostgreSQL commits, and in which order the relay reads it, is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_131'), 'async award(userId: string, amount: number, reason: string) {
  await this.dataSource.transaction(async (manager) => {
    const wallet = await manager.findOneOrFail(Wallet, { where: { userId }, lock: { mode: "pessimistic_write" } });
    wallet.points += amount;
    await this.outbox.save({ aggregateType: "wallet", aggregateId: userId,
      eventType: "points.awarded", payload: { userId, amount, reason, balance: wallet.points } });
    if (wallet.points > MAX_POINTS) throw new BadRequestException("balance cap reached");
    await manager.save(wallet);
  });
}
// this.outbox is injected with @InjectRepository(OutboxEvent): it is bound to the DataSource, not to manager.

Statement: "When the balance cap check throws, the wallet change is rolled back but the points.awarded outbox row stays committed, and the relay will publish it."', 'single_choice'::question_type, 'True. Only queries that go through manager run on the connection that executed BEGIN. The injected repository takes its own pooled connection and runs the INSERT as a single-statement transaction that commits immediately. When the callback throws, TypeORM rolls back the manager''s transaction (the wallet), but the outbox row was committed before, on another backend, so the relay publishes a ghost award. The fix is manager.getRepository(OutboxEvent) or manager.save(OutboxEvent, ...), and validating before writing. The misconception is that everything written inside the transaction callback belongs to the transaction.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_131'), 'CREATE TABLE outbox (
  id         uuid PRIMARY KEY,
  event_type text NOT NULL,
  payload    jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  status     text NOT NULL DEFAULT ''pending''
);

-- completeLesson, one transaction:
BEGIN;
INSERT INTO lesson_progress (user_id, lesson_id) VALUES (''u_77'', ''l_12'');
INSERT INTO outbox (id, event_type, payload) VALUES (gen_random_uuid(), ''lesson.completed'', ''{...}'');
INSERT INTO outbox (id, event_type, payload) VALUES (gen_random_uuid(), ''course.completed'', ''{...}'');
COMMIT;

-- relay:
SELECT id, event_type FROM outbox WHERE status = ''pending'' ORDER BY created_at LIMIT 100;

Statement: "The relay reads lesson.completed before course.completed, because the first row was inserted earlier and got an earlier created_at."', 'single_choice'::question_type, 'False. now() (and CURRENT_TIMESTAMP) returns the start time of the current transaction, so both rows get exactly the same created_at, and ORDER BY created_at leaves their order to the plan: a consumer may receive course.completed before lesson.completed. clock_timestamp() would differ per row, but timestamps are still a weak ordering key; a bigserial seq column records the insert order within the transaction and is what the relay should order by. The misconception is that a timestamp default records the moment each row was inserted.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_dce_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dce_132', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-1-3' AND is_deleted = false LIMIT 1), 'outbox-same-transaction-commands', 'Outbox in the same transaction', 'CodeDev''s enrollment and wallet services publish through a transactional outbox: a command writes its business change and the events describing it in one db.tx(); a relay (not part of this task) publishes the pending outbox rows later. Implement the two commands so that each one is either fully committed with all its events, or leaves nothing at all.

placeEnrollment(deps, { userId, courseId })
- Reject, checked in this order: "unknown user" (no wallet for userId), "unknown course", "already enrolled", "course full" (enrolled has reached seats).
- Write an enrollments row { id: ids.next("enr"), userId, courseId, createdAt: clock.now() } and add 1 to courses[courseId].enrolled.
- Events: enrollment.created (aggregate "enrollment" / enrollment id, payload { enrollmentId, userId, courseId }); then, only if this enrollment took the last seat, course.full (aggregate "course" / courseId, payload { courseId, seats }).

awardPoints(deps, { userId, amount, reason })
- Reject, checked in this order: "unknown user", "invalid amount" (amount is not an integer from 1 to 10000; it can arrive as any JSON value), "missing reason" (reason is not a non-empty string).
- Add amount to wallets[userId].points.
- Events: points.awarded (aggregate "wallet" / userId, payload { userId, amount, reason, balance } where balance is the new points), then one level.reached (aggregate "wallet" / userId, payload { userId, level }) for every level crossed, lowest first, where level = Math.floor(points / 1000).

Each event is an outbox row { id: ids.next("evt"), aggregateType, aggregateId, eventType, payload, createdAt: clock.now(), status: "pending" } with the payload keys in the order listed. Take ids only after validation passed: the enrollment id first, then one event id per event in event order (a sequence: ids taken by a transaction that does not commit are not reused). A rejection throws new Rejected("<reason>") and writes nothing.

Input (stdin, JSON): { courses: [{ id, title, seats }], wallets: [{ userId, points }], commands }. A command is { op: "place", userId, courseId, crash? } or { op: "award", userId, amount, reason, crash? }. crash is "beforeCommit" or "afterCommit": the test runner kills the process at that point of the command''s first transaction and restarts it before the next command.
Output: one line per command ("ok", "rejected (<reason>)" or "no response (process crashed <point>)"), then the database: courses as "<id> <enrolled>/<seats>", enrollments, wallets and every outbox row "<id> <aggregateType>/<aggregateId> <eventType> <payload JSON> <createdAt> <status>" in insertion order.
Constraints: up to 300 commands, 10 courses, 100 wallets. Use db.tx(); do not change FakeDb, Ids, Clock or the test runner.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_132');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_132'), 1, 'If the process dies right after the first COMMIT of a command, what must already be in the database for the relay to publish the command''s events later? And if a rule rejects the command after something was written, what must the transaction do?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_132'), 2, 'Look at FakeDb.tx: it commits the copy only when your callback returns normally. Put every check, every business write and every outbox row of one command in a single callback, check first, and throw Rejected (never return) when a rule fails. For levels, compare Math.floor of the points before and after the award.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_132'), 3, 'A similar command on different data: completeLesson in one tx checks the lesson exists and the learner is enrolled (throwing on failure), inserts the progress row, then adds lesson.completed and, if no lesson of the course is left, course.completed, in that order, each with ids.next("evt"). A badge counter that goes from 2 to 7 with a badge every 3 crosses 3 and 6: two events, 3 first.');
