-- challenge chal_quiz_dce_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dce_211', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-2-1' AND is_deleted = false LIMIT 1), 'outbox-publisher-quiz', 'What does the relay publish after a crash or a broker error?', 'Two pieces of evidence from the enrollments outbox relay: a relay killed between publish and mark, and a claim query that delays a failed row.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_211');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_211'), 'Relay loop (per claimed row): publish to the broker, then UPDATE outbox SET status = ''sent'' WHERE id = $1 AND lease_owner = $2. Leases last 30 s.

10:02:03.120  relay-a  published outbox #881 (enrollment e-7, enrollment.created)
10:02:03.125  kubelet  relay-a container OOMKilled
10:02:03.200  outbox   #881 status=pending lease_owner=relay-a lease_until=10:02:33
10:02:33.410  relay-b  claimed #881 #882
10:02:33.452  relay-b  published outbox #881 (enrollment e-7, enrollment.created)

Statement: "Publishing #881 a second time is the expected behaviour of this relay, so the consumers of enrollment.created must treat the second copy as a duplicate."', 'single_choice'::question_type, 'True. Publishing and marking the row are writes to two different systems, so a crash can always fall between them. This relay chose the safe side: it publishes first and marks after, and a row whose mark never committed is published again once its lease expires. That is at-least-once delivery: no event is lost, and an event can arrive twice with the same outbox id. The consumers deduplicate on that id (next lesson). The misconception is that a careful relay can avoid duplicates entirely; marking first would only trade the duplicate for a lost event when the crash or a broker error comes after the mark.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_211'), 'Claim query of the relay:

SELECT id, aggregate_id, type, payload FROM outbox
WHERE status = ''pending'' AND next_attempt_at <= now()
ORDER BY id
LIMIT 100
FOR UPDATE SKIP LOCKED;

On a broker error the relay runs UPDATE outbox SET attempts = attempts + 1, next_attempt_at = now() + interval ''30 seconds'' WHERE id = $1.

At 09:00:00 the publish of #120 (enrollment e-7, enrollment.created) fails. #121 (enrollment e-7, progress.updated) is pending with next_attempt_at = 09:00:00.

Statement: "Because the claim query orders by id, the progress.updated event of e-7 cannot reach the broker before its enrollment.created event."', 'single_choice'::question_type, 'False. ORDER BY id only orders the rows that pass the WHERE clause. For the next 30 seconds #120 fails next_attempt_at <= now(), so it is not in the result at all, while #121 is; the relay claims and publishes #121 first, and the certificate service sees progress for an enrollment it does not know. To keep order per aggregate, an unsent earlier row of the same aggregate (delayed, failed or leased by another relay) must block the later rows of that aggregate, while other aggregates keep flowing. The misconception is that sorting a query result gives an order guarantee across retries.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_dce_212 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dce_212', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-2-1' AND is_deleted = false LIMIT 1), 'outbox-publisher-relay', 'An outbox relay with leases, backoff and per-aggregate order', 'The CodeDev enrollments service writes every event into an outbox table in the same transaction as the enrollment. Relay processes ("A", "B", ...) copy the rows to the broker. Write `claimBatch` and `publishClaimed` so that the relay publishes at least once, never publishes two rows of the same claim twice, keeps the order of events per aggregate, backs off on broker errors and survives a crash between publish and mark.

Row fields: `id`, `aggregate`, `type`, `status` ("pending" | "sent" | "failed"), `attempts`, `nextAttemptAt`, `leaseOwner` (string or null), `leaseUntil`, `sentAt`. Times are milliseconds on a fake clock (`now`).

`claimBatch(db, owner, now, cfg)` runs in one `db.tx`. Walk every row whose status is not "sent", in id order. Skip the row if its aggregate is already blocked in this walk. Block its aggregate (and skip the row) if the row is "failed", or `nextAttemptAt > now`, or another owner holds a live lease (`leaseOwner !== owner` and `leaseUntil > now`; a lease with `leaseUntil <= now` has expired). Otherwise claim it while fewer than `cfg.batchSize` rows are claimed (`leaseOwner = owner`, `leaseUntil = now + cfg.leaseMs`); stop the walk when the batch is full. Return the claimed ids in ascending order. If `cfg.batchSize` or `cfg.leaseMs` is not a positive integer, throw `new Error("invalid config")` and claim nothing.

`publishClaimed(db, broker, owner, now, cfg)` reads the rows with status "pending", `leaseOwner === owner` and `leaseUntil > now`, in id order. For each row whose aggregate is not blocked in this call: `broker.publish(TOPIC, { id, key: aggregate, payload: { type } })`. On success, in its own `db.tx`, set status "sent", `sentAt = now`, `leaseOwner = null`, `leaseUntil = 0`. On a `BrokerError`, in a `db.tx`, add 1 to `attempts`; when `attempts` reaches `cfg.maxAttempts` set status "failed", otherwise `nextAttemptAt = now + cfg.backoffMs * 2 ** (attempts - 1)`; release the lease (`leaseOwner = null`, `leaseUntil = 0`) and block the aggregate for the rest of the call. Finally, in one `db.tx`, release the lease of every row still "pending" with `leaseOwner === owner`.

Never catch `Crash`: the runner scripts a crash right after the Nth successful publish of a step; the database then refuses every later write of that process, and the next step is a fresh process.

Input (JSON): `{ "config": { batchSize, leaseMs, backoffMs, maxAttempts }, "outbox": [{ "aggregate", "type" }], "steps": [...] }`. Rows get ids 1, 2, 3, ... and start pending. Steps: `{ "tick": "A" }` (claimBatch then publishClaimed), `{ "claim": "A" }`, `{ "publish": "A" }`, `"crashAfter": N` on a tick or publish step, `{ "advance": ms }`, `{ "brokerFails": N }` (the next N publish calls fail), `{ "insert": [{ "aggregate", "type" }] }`.

Output (printed by the runner): one line per claim, publish, broker error, crash and insert, then `outbox: <sent> sent, <pending> pending, <failed> failed` and one line for each row that is not sent.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_212');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_212'), 1, 'Relay A holds a live lease on event #2 of enrollment enr-2. What may relay B do with event #3 of the same enrollment, and why may it still take the events of enr-3?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_212'), 2, 'Check three places: the conditions that make a row block its aggregate in claimBatch (failed, nextAttemptAt in the future, another owner''s live lease), the order of broker.publish and the transaction that marks the row sent, and which rows publishClaimed reads (only the leases you still hold at `now`).'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_212'), 3, 'A similar walk on other rows: #1 x, #2 y, #3 x, with #1 delayed until t=1000 and batchSize 5. At t=0 the walk blocks x at #1, claims #2 and skips #3 because x is blocked, so claimBatch returns [2]. At t=1000 it claims #1 and #3, in that order. If publishing #1 then fails, #3 stays unpublished in that call.');
