VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_212'), 'One relay publishes batch by batch in id order and marks each row sent', '{"config":{"batchSize":3,"leaseMs":30000,"backoffMs":1000,"maxAttempts":3},"outbox":[{"aggregate":"enr-1","type":"enrolled"},{"aggregate":"enr-2","type":"enrolled"},{"aggregate":"enr-1","type":"progress"},{"aggregate":"enr-3","type":"enrolled"},{"aggregate":"enr-2","type":"progress"}],"steps":[{"tick":"A"},{"advance":100},{"tick":"A"},{"advance":100},{"tick":"A"}]}', '"t=0 A claimed #1 #2 #3\nt=0 A published #1 enr-1 enrolled\nt=0 A published #2 enr-2 enrolled\nt=0 A published #3 enr-1 progress\nt=100 A claimed #4 #5\nt=100 A published #4 enr-3 enrolled\nt=100 A published #5 enr-2 progress\nt=200 A claimed nothing\noutbox: 5 sent, 0 pending, 0 failed"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_212'), 'A broker error backs off one aggregate while the other aggregates keep flowing', '{"config":{"batchSize":10,"leaseMs":30000,"backoffMs":1000,"maxAttempts":3},"outbox":[{"aggregate":"enr-1","type":"enrolled"},{"aggregate":"enr-2","type":"enrolled"},{"aggregate":"enr-1","type":"progress"},{"aggregate":"enr-3","type":"enrolled"}],"steps":[{"brokerFails":1},{"tick":"A"},{"advance":500},{"tick":"A"},{"advance":500},{"tick":"A"}]}', '"t=0 A claimed #1 #2 #3 #4\nt=0 A broker error on #1\nt=0 A published #2 enr-2 enrolled\nt=0 A published #4 enr-3 enrolled\nt=500 A claimed nothing\nt=1000 A claimed #1 #3\nt=1000 A published #1 enr-1 enrolled\nt=1000 A published #3 enr-1 progress\noutbox: 4 sent, 0 pending, 0 failed"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_212'), 'Crash between publish and mark: the event is published again once the lease expires', '{"config":{"batchSize":10,"leaseMs":30000,"backoffMs":1000,"maxAttempts":3},"outbox":[{"aggregate":"enr-1","type":"enrolled"},{"aggregate":"enr-2","type":"enrolled"},{"aggregate":"enr-2","type":"progress"},{"aggregate":"enr-3","type":"enrolled"}],"steps":[{"tick":"A","crashAfter":2},{"advance":5000},{"tick":"B"},{"advance":25000},{"tick":"B"}]}', '"t=0 A claimed #1 #2 #3 #4\nt=0 A published #1 enr-1 enrolled\nt=0 A published #2 enr-2 enrolled\nt=0 A crashed\nt=5000 B claimed nothing\nt=30000 B claimed #2 #3 #4\nt=30000 B published #2 enr-2 enrolled\nt=30000 B published #3 enr-2 progress\nt=30000 B published #4 enr-3 enrolled\noutbox: 4 sent, 0 pending, 0 failed"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_212'), 'Two relays claim before either publishes: no row twice, each aggregate stays in order', '{"config":{"batchSize":2,"leaseMs":30000,"backoffMs":1000,"maxAttempts":3},"outbox":[{"aggregate":"enr-1","type":"enrolled"},{"aggregate":"enr-2","type":"enrolled"},{"aggregate":"enr-1","type":"progress"},{"aggregate":"enr-3","type":"enrolled"},{"aggregate":"enr-2","type":"progress"},{"aggregate":"enr-4","type":"enrolled"}],"steps":[{"claim":"A"},{"claim":"B"},{"publish":"B"},{"publish":"A"},{"advance":100},{"tick":"B"}]}', '"t=0 A claimed #1 #2\nt=0 B claimed #4 #6\nt=0 B published #4 enr-3 enrolled\nt=0 B published #6 enr-4 enrolled\nt=0 A published #1 enr-1 enrolled\nt=0 A published #2 enr-2 enrolled\nt=100 B claimed #3 #5\nt=100 B published #3 enr-1 progress\nt=100 B published #5 enr-2 progress\noutbox: 6 sent, 0 pending, 0 failed"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_212'), 'Expired lease: the old owner publishes nothing, the new owner publishes the rows', '{"config":{"batchSize":3,"leaseMs":30000,"backoffMs":1000,"maxAttempts":3},"outbox":[{"aggregate":"enr-1","type":"enrolled"},{"aggregate":"enr-2","type":"enrolled"},{"aggregate":"enr-1","type":"progress"}],"steps":[{"claim":"A"},{"advance":30000},{"claim":"B"},{"publish":"A"},{"publish":"B"},{"insert":[{"aggregate":"enr-2","type":"completed"}]},{"claim":"A"},{"advance":30000},{"publish":"A"},{"tick":"B"}]}', '"t=0 A claimed #1 #2 #3\nt=30000 B claimed #1 #2 #3\nt=30000 B published #1 enr-1 enrolled\nt=30000 B published #2 enr-2 enrolled\nt=30000 B published #3 enr-1 progress\nt=30000 app inserted #4\nt=30000 A claimed #4\nt=60000 B claimed #4\nt=60000 B published #4 enr-2 completed\noutbox: 4 sent, 0 pending, 0 failed"', 3, false, true, 5),
