-- challenge chal_quiz_dce_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dce_221', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-2-2' AND is_deleted = false LIMIT 1), 'inbox-dedup-quiz', 'Is the duplicate skipped, counted or lost?', 'Two consumers of certificate.issued: one that deduplicates in Redis before writing to PostgreSQL, and one with an inbox table hit by two sessions at once.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
