DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_221'), 'async function onCertificateIssued(msg: Message) {
  const first = await redis.set(`seen:${msg.id}`, "1", { NX: true, EX: 86400 });
  if (!first) return msg.ack();                      // already processed
  await pg.query("UPDATE course_stats SET certificates = certificates + 1 WHERE course_id = $1", [msg.payload.courseId]);
  msg.ack();
}

11:20:41.003  consumer-2  SET seen:m-4410 NX -> OK
11:20:41.004  kubelet     consumer-2 OOMKilled
11:20:52.870  consumer-3  received m-4410 (redelivered)

Statement: "When m-4410 is redelivered to consumer-3, the certificate is counted, because the Redis key only marks messages that were acked."', 'single_choice'::question_type, 'False. The key was written by SET NX before the UPDATE, and Redis does not know whether the UPDATE or the ack ever happened. consumer-3 finds seen:m-4410, takes the ''already processed'' branch and acks: the certificate is never counted. The deduplication record and the effect live in two different stores, so they cannot commit together; moving the SET after the UPDATE only flips the failure into a double count. The fix is to record the message id in the same PostgreSQL transaction as the UPDATE. The misconception is that a fast dedup cache in front of the database is atomic with the database write.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_221'), 'inbox has PRIMARY KEY (consumer, message_id). During a rebalance, two consumers briefly process the same message (READ COMMITTED):

A: BEGIN;
A: INSERT INTO inbox (consumer, message_id) VALUES (''cert-counters'', ''m-77'') ON CONFLICT DO NOTHING;   -- INSERT 0 1
B: BEGIN;
B: INSERT INTO inbox (consumer, message_id) VALUES (''cert-counters'', ''m-77'') ON CONFLICT DO NOTHING;   -- (waits)
A: UPDATE course_stats SET certificates = certificates + 1 WHERE course_id = ''sql-101'';
A: COMMIT;
B:                                                                                            -- INSERT 0 0

Statement: "B''s insert waited for A''s uncommitted row with the same key and, once A committed, took the conflict path; the handler must treat INSERT 0 0 as a duplicate and skip the UPDATE."', 'single_choice'::question_type, 'True. A unique index makes a second insert of the same key wait for the transaction that inserted it first. If that transaction commits, ON CONFLICT DO NOTHING inserts nothing and reports 0 rows; if it rolls back, the second insert goes through. So the row count of the inbox insert is the answer to ''did someone else already process this message?'', and it is correct even when two consumers race. The handler skips the effect, commits and acks. The misconception is that a check-then-insert (SELECT, then INSERT) is equivalent: two sessions can both see ''not found'' and both apply the effect.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_dce_222 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dce_222', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-2-2' AND is_deleted = false LIMIT 1), 'inbox-dedup-certificate-counters', 'An inbox for the certificate counters', 'The CodeDev course dashboard shows how many certificates each course has issued. The certificates service publishes `certificate.issued` events (payload `{ courseId, userId }`) and the broker delivers at least once: a message that was not acked, because the consumer crashed, is delivered again. The counters drifted above the real number of certificates. Write `InboxConsumer` so that every message changes the counters at most once while its id is remembered.

`handle(msg, now)` returns "processed", "duplicate" or "invalid":
- "invalid" when `msg.id` or `msg.payload.courseId` is not a non-empty string: change nothing;
- "duplicate" when the inbox already has a row for `msg.id`: change nothing;
- "processed" otherwise: in ONE `db.tx`, insert the inbox row (`msg.id` -> `{ processedAt: now }`) and add 1 to `counters[courseId]` (a missing counter counts as 0). The check belongs in the same transaction.

`cleanup(now, retentionMs)` deletes, in one `db.tx`, every inbox row with `now - processedAt >= retentionMs` and returns how many rows it deleted. The inbox only remembers ids inside the retention window: a message delivered again after its row was deleted is processed again. That is the documented limit of this design.

The tests crash the process just before or just after the commit of the transaction that changes the counters. After a crash the runner starts a new `InboxConsumer` on the same database: anything kept in the consumer object is lost. Never catch `Crash`.

Input (JSON): a list of steps: `{ "deliver": { "id", "courseId", "userId" }, "crash"?: "beforeCommit" | "afterCommit" }`, `{ "advance": ms }` (fake clock), `{ "cleanup": retentionMs }`.

Output (printed by the runner): one line per delivery (`t=<now> <id> <course>: processed, acked` / `duplicate, acked` / `invalid, acked` / `crashed before commit, not acked` / `crashed after commit, not acked`), one line per cleanup (`cleanup removed N`), then `counters: <course>=<n> ...` and `inbox: <n> rows`.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_222');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_222'), 1, 'The process dies right after the counter commit and before the ack, and the same message comes back to a brand-new consumer object. What survived the crash that can tell the new consumer it has already counted this id?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_222'), 2, 'Look at where handle reads the inbox and where it writes the counter: the check, the inbox row and the counter must all happen inside the same db.tx callback. In cleanup, look at the comparison with retentionMs for a row that is exactly retentionMs old.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_222'), 3, 'A similar consumer counts lessons done per user. Delivery l7 at t=0 commits { inbox l7, lessonsDone[u4] + 1 } in one transaction, then crashes before the ack; the redelivery finds l7 in the inbox and returns duplicate. With a retention of 1000 ms, cleanup at t=1000 deletes l7 (1000 - 0 >= 1000), so a delivery of l7 at t=1500 is counted again.');
