-- lesson 2.3: Spot the AI mistake: a consumer that adds points twice (Sanity lesson-dce-2-3)
UPDATE course.lesson SET title = 'Spot the AI mistake: a consumer that adds points twice', order_index = 3, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 2 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-2-3' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 2 AND is_deleted = false LIMIT 1), 'Spot the AI mistake: a consumer that adds points twice', 'sanity', 'lesson-dce-2-3', 3
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-dce-2-3' AND is_deleted = false);

-- challenge chal_quiz_dce_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dce_231', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-2-3' AND is_deleted = false LIMIT 1), 'non-idempotent-consumer-quiz', 'Which points were added twice?', 'The wallet consumer an AI wrote, hit by a crash between commit and ack, and a proposed fix that deduplicates on offsets.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_231'), 'Handler (from the AI), on a queue that redelivers unacked messages:
await pg.query("UPDATE wallets SET balance = balance + $2 WHERE user_id = $1", [e.userId, e.amount]);
await msg.ack();

wallets before: u-44 balance = 120
11:30:02.101  wallet-1  handled p-7720 (u-44, +30), transaction committed
11:30:02.102  kubelet   wallet-1 OOMKilled
11:30:12.400  wallet-3  received p-7720 (redelivered)
11:30:12.415  wallet-3  handled p-7720 (u-44, +30), transaction committed, acked

Statement: "u-44 now has a balance of 180, although event p-7720 awarded 30 points once."', 'single_choice'::question_type, 'True. wallet-1 committed the UPDATE (120 + 30 = 150) and died before the ack, so the queue still considered p-7720 unprocessed and delivered it again. wallet-3 ran the same UPDATE on the committed balance: 150 + 30 = 180. The transaction made each delivery atomic, but nothing recorded that p-7720 had already been applied, and balance = balance + amount adds again on every delivery. The misconception is that a committed transaction plus an ack after it is enough; the window between commit and ack is exactly where duplicates come from.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_231'), 'Proposed fix (also from the AI): store the last processed offset per partition in the same transaction as the balance change, and skip any message whose offset is not greater.

BEGIN;
SELECT last_offset FROM consumer_offsets WHERE partition = 3;            -- 7709
UPDATE wallets SET balance = balance + 50 WHERE user_id = ''u-18'';
UPDATE consumer_offsets SET last_offset = 7710 WHERE partition = 3;
COMMIT;

The outbox relay of the points service crashed between publish and mark, so event p-9001 was published twice: at offset 7702 and again at offset 7710.

Statement: "With this fix, the second copy of p-9001 at offset 7710 is skipped."', 'single_choice'::question_type, 'False. An offset identifies a position in the log, not an event. The relay''s second publish wrote p-9001 at a new, higher offset, so 7710 > 7709 and the handler applies the 50 points again. Storing offsets transactionally protects against the broker replaying the same positions (as after a rebalance), but not against a producer that publishes the same event twice, nor against a queue that redelivers a message after newer ones. Deduplicate on the event id the producer assigned, recorded in the same transaction as the balance change. The misconception is that a duplicate always has the same offset.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_dce_232 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dce_232', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-2-3' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-points-twice', 'Spot the AI Mistake: a consumer that adds points twice', 'An AI coding assistant was asked: "write a consumer that adds the points from `points.awarded` events to the wallet balance". It wrote `WalletConsumer`: it validates the payload, adds `amount` to the balance inside a transaction, and its tests, one delivery per event, pass. After a deploy restarted the consumers and the consumer group rebalanced, messages that had been processed but not acked were delivered again, and learners reported that their points had doubled; the leaderboard reads these balances.

Fix `WalletConsumer` so that every `points.awarded` event changes the balance exactly once, however many times and in whatever order it is delivered, across crashes and restarts:
- `handle(msg)` returns "applied" the first time an event id changes a balance, "duplicate" (no change) for an event id that already changed it, and "invalid" (no change) when `msg.id` or `payload.userId` is not a non-empty string or `payload.amount` is not a positive integer;
- two different events with the same user and amount are two awards: both are applied;
- the tests may crash the process just before or just after the commit of the transaction that changes `wallets`, and a rebalance or a crash hands the partition to a new `WalletConsumer` on the same database (anything kept in the consumer object is lost); a message that was not acked comes again, possibly after newer ones.

Accepted protocols: record the event id in `processed_events` (an inbox), or in `points_ledger` (a ledger keyed by event id from which the balance follows), in the same `db.tx` as the change to `wallets`. The runner prints only what `handle` returns and the final balances, so either protocol gives the same output. Never catch `Crash`.

Input (JSON): a list of steps: `{ "deliver": { "id", "userId", "amount" }, "crash"?: "beforeCommit" | "afterCommit" }` or `{ "rebalance": true }`. Output: one line per delivery (`<id> <user> +<amount>: applied, acked` / `duplicate, acked` / `invalid, acked` / `crashed before commit, not acked` / `crashed after commit, not acked`), a line per rebalance, then `wallets: <user>=<balance> ...`. The public tests pass on the AI''s code; the hidden tests deliver duplicates, reorder them and crash before the ack.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 1, 'When the same event id arrives a second time, possibly at a new consumer after a rebalance, what in the database could tell the handler that its points are already in the balance?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 2, 'Look at the transaction in handle: it changes wallets but writes nothing about msg.id. The schema already has processed_events and points_ledger. Which one would you write in that same transaction, what must happen when the id is already there, and what can you do with a message that has no id?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 3, 'A similar consumer grants badges: badge.granted b-12 for u5. In one transaction it inserts b-12 into its processed table; if b-12 was already there it returns duplicate and changes nothing, otherwise it adds the badge. Deliveries b-12, b-13, a restart, then b-12 again give applied, applied, duplicate, and u5 has 2 badges. A crash before that transaction commits leaves no trace, so the next b-12 is applied.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 'One delivery per event: the balances add up', '[{"deliver":{"id":"p1","userId":"u1","amount":50}},{"deliver":{"id":"p2","userId":"u2","amount":20}},{"deliver":{"id":"p3","userId":"u1","amount":30}}]', '"p1 u1 +50: applied, acked\np2 u2 +20: applied, acked\np3 u1 +30: applied, acked\nwallets: u1=80 u2=20"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 'Two awards with the same user and amount are two awards', '[{"deliver":{"id":"p1","userId":"u1","amount":50}},{"deliver":{"id":"p2","userId":"u1","amount":50}},{"deliver":{"id":"p3","userId":"u2","amount":10}}]', '"p1 u1 +50: applied, acked\np2 u1 +50: applied, acked\np3 u2 +10: applied, acked\nwallets: u1=100 u2=10"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 'Invalid payloads (zero, negative, fractional amount, no user) change nothing', '[{"deliver":{"id":"p1","userId":"u1","amount":0}},{"deliver":{"id":"p2","userId":"u1","amount":-5}},{"deliver":{"id":"p3","userId":"u1","amount":2.5}},{"deliver":{"id":"p4","userId":"","amount":10}},{"deliver":{"id":"p5","userId":"u1","amount":10}}]', '"p1 u1 +0: invalid, acked\np2 u1 +-5: invalid, acked\np3 u1 +2.5: invalid, acked\np4 (no user) +10: invalid, acked\np5 u1 +10: applied, acked\nwallets: u1=10"', 2, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 'Rebalance: processed but unacked events come again and change nothing', '[{"deliver":{"id":"p1","userId":"u1","amount":50}},{"deliver":{"id":"p2","userId":"u2","amount":20}},{"deliver":{"id":"p3","userId":"u1","amount":30}},{"deliver":{"id":"p4","userId":"u3","amount":100}},{"rebalance":true},{"deliver":{"id":"p3","userId":"u1","amount":30}},{"deliver":{"id":"p4","userId":"u3","amount":100}},{"deliver":{"id":"p5","userId":"u2","amount":10}}]', '"p1 u1 +50: applied, acked\np2 u2 +20: applied, acked\np3 u1 +30: applied, acked\np4 u3 +100: applied, acked\nrebalance: partition assigned to a new consumer\np3 u1 +30: duplicate, acked\np4 u3 +100: duplicate, acked\np5 u2 +10: applied, acked\nwallets: u1=80 u2=30 u3=100"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 'Crash after commit, before ack: the redelivery is a duplicate', '[{"deliver":{"id":"p1","userId":"u1","amount":50},"crash":"afterCommit"},{"deliver":{"id":"p1","userId":"u1","amount":50}},{"deliver":{"id":"p2","userId":"u1","amount":20}},{"deliver":{"id":"p2","userId":"u1","amount":20}}]', '"p1 u1 +50: crashed after commit, not acked\np1 u1 +50: duplicate, acked\np2 u1 +20: applied, acked\np2 u1 +20: duplicate, acked\nwallets: u1=70"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 'Out of order: an event that crashed before commit returns after newer events', '[{"deliver":{"id":"p1","userId":"u1","amount":50},"crash":"beforeCommit"},{"deliver":{"id":"p2","userId":"u1","amount":20}},{"deliver":{"id":"p3","userId":"u2","amount":10}},{"deliver":{"id":"p1","userId":"u1","amount":50}},{"deliver":{"id":"p2","userId":"u1","amount":20}}]', '"p1 u1 +50: crashed before commit, not acked\np2 u1 +20: applied, acked\np3 u2 +10: applied, acked\np1 u1 +50: applied, acked\np2 u1 +20: duplicate, acked\nwallets: u1=70 u2=10"', 3, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 'A message without an event id cannot be deduplicated and is rejected', '[{"deliver":{"userId":"u1","amount":50}},{"deliver":{"id":"","userId":"u1","amount":50}},{"deliver":{"id":"p1","userId":"u1","amount":50}}]', '"(no id) u1 +50: invalid, acked\n(no id) u1 +50: invalid, acked\np1 u1 +50: applied, acked\nwallets: u1=50"', 2, false, true, 7),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_232'), 'Large stream: 700+ deliveries with rebalances, crashes, duplicates and reordering', '[{"deliver":{"id":"p1","userId":"u54","amount":100}},{"deliver":{"id":"p2","userId":"u17","amount":10}},{"deliver":{"id":"p3","userId":"u55","amount":50}},{"deliver":{"id":"p1","userId":"u54","amount":100}},{"deliver":{"id":"p4","userId":"u59","amount":50}},{"deliver":{"id":"p5","userId":"u60","amount":20}},{"deliver":{"id":"p6","userId":"u8","amount":5}},{"deliver":{"id":"p7","userId":"u34","amount":20}},{"deliver":{"id":"p8","userId":"u24","amount":50}},{"deliver":{"id":"p9","userId":"u50","amount":50}},{"deliver":{"id":"p10","userId":"u35","amount":20}},{"deliver":{"id":"p11","userId":"u39","amount":10}},{"deliver":{"id":"p12","userId":"u31","amount":10},"crash":"beforeCommit"},{"deliver":{"id":"p13","userId":"u48","amount":10}},{"deliver":{"id":"p14","userId":"u12","amount":50}},{"deliver":{"id":"p15","userId":"u37","amount":5}},{"deliver":{"id":"p16","userId":"u43","amount":10}},{"deliver":{"id":"p12","userId":"u31","amount":10}},{"deliver":{"id":"p17","userId":"u17","amount":5}},{"deliver":{"id":"p18","userId":"u55","amount":10}},{"deliver":{"id":"p19","userId":"u47","amount":50}},{"deliver":{"id":"p20","userId":"u29","amount":100}},{"deliver":{"id":"p21","userId":"u41","amount":50}},{"deliver":{"id":"p9","userId":"u50","amount":50}},{"deliver":{"id":"p22","userId":"u36","amount":10},"crash":"beforeCommit"},{"deliver":{"id":"p23","userId":"u37","amount":10}},{"deliver":{"id":"p24","userId":"u1","amount":50}},{"deliver":{"id":"p25","userId":"u13","amount":20}},{"deliver":{"id":"p26","userId":"u16","amount":100}},{"deliver":{"id":"p22","userId":"u36","amount":10}},{"deliver":{"id":"p27","userId":"u60","amount":5}},{"deliver":{"id":"p28","userId":"u51","amount":50}},{"deliver":{"id":"p17","userId":"u17","amount":5}},{"deliver":{"id":"p7","userId":"u34","amount":20}},{"deliver":{"id":"p29","use