-- challenge chal_quiz_dce_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dce_311', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-3-1' AND is_deleted = false LIMIT 1), 'ordering-by-key-quiz', 'Read the consumer logs: where did the order go?', 'Two pieces of evidence from the progress pipeline: a producer that keys events by event id, and a consumer that processes a fetched batch with Promise.all.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_311');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_311');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_311'), 'The progress service''s outbox publisher (topic progress-events, 6 partitions, the default partitioner picks the partition from a hash of the key):

await producer.send({
  topic: "progress-events",
  messages: [{ key: row.event_id, value: JSON.stringify(row.payload) }],
});

Two events of the same learner, published 40 ms apart:

event_id=7f1c-...  learner=u_17  type=progress.updated  percent=90   -> partition 4, offset 88123
event_id=a20e-...  learner=u_17  type=progress.updated  percent=100  -> partition 1, offset 90417

The progress read model has one consumer instance per partition.

Statement: "The read model can apply percent=100 before percent=90 for u_17, even though the broker keeps every partition in order."', 'single_choice'::question_type, 'True. Order is kept inside one partition only. The key decides the partition, and a random event id sends two events of the same learner to two different partitions, read by two consumer instances that run independently: whichever instance is less busy applies its event first. If the 90% event lands second, the learner''s progress goes back from 100 to 90. The fix is to key by the aggregate the order matters for - the learner id (or the enrollment id) - so every event of one learner lands in one partition. The misconception is that "the broker is ordered" means globally ordered; Kafka orders per partition, SQS FIFO per message group, and a RabbitMQ queue loses its order as soon as several consumers share it.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_311'), 'After the fix the events are keyed by learner id. To cut the lag, a developer changes the consumer of partition 4:

consumer.run({
  eachBatch: async ({ batch }) => {
    await Promise.all(batch.messages.map((m) => applyProgress(JSON.parse(m.value))));
  },
});

Consumer log (applyProgress writes progress.percent for the learner):

14:02:07.112 start  p4 offset=88123 u_17 percent=90   (UPDATE waits for a row lock 180 ms)
14:02:07.113 start  p4 offset=88124 u_17 percent=100
14:02:07.151 done   p4 offset=88124 u_17 percent=100
14:02:07.297 done   p4 offset=88123 u_17 percent=90

Statement: "Since every message in the batch comes from one partition, Promise.all still applies each learner''s events in offset order."', 'single_choice'::question_type, 'False. Promise.all starts every handler at once and waits for all of them; it does not wait for one to finish before starting the next. Offset 88123 started first but its UPDATE waited on a lock, so offset 88124 finished first and the older value (90) was written last. The partition delivered the messages in order; the consumer threw that order away by running two events of the same key concurrently. Keep the concurrency, but only across keys: group the batch by key and process each group one after the other (or use a per-key queue), so u_17''s events run in sequence while other learners run in parallel. The misconception is that the order of delivery is the order of completion.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_311') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_dce_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dce_312', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-3-1' AND is_deleted = false LIMIT 1), 'ordering-per-key-dispatcher', 'A worker pool that keeps each learner''s events in order', 'The CodeDev leaderboard consumer was made concurrent to cut its lag, and learners'' progress started to go backwards: two events of one learner ran at the same time and the older one finished last. Write KeyedDispatcher, the part of the worker pool that decides which event a free worker starts next. Every event has the learner id as key and a per-learner sequence number seq (the first event of a learner is seq 1). receive(msg) is called when an event is delivered and returns "rejected" when key is not a non-empty string or seq is not an integer >= 1 (dead-letter queue, nothing else changes), "dropped" when seq is lower than the key''s next expected seq or that seq is already held (a duplicate, or a late event whose gap was given up), else "held". take() returns the event a free worker should start now, or null: an event can start when its seq equals its key''s next expected seq and no other event of the same key is being processed; among those, the one received first. A taken event is no longer held and its key''s next expected seq becomes seq + 1 at once. complete(msg) frees the key. A key has a gap while it holds events and the lowest held seq is greater than its next expected seq; the gap''s timer starts at the clock time the gap appears (in receive or take) and stops when it disappears. expireGaps() gives up every gap that has existed for gapTimeoutMs or more (now - since >= gapTimeoutMs): it returns { key, from: next expected seq, to: lowest held seq - 1 } and makes the lowest held seq the next expected one. nextGapDeadline() returns the earliest time a current gap times out, or null. A busy key or a key waiting for a gap must never stop other keys. Use only the injected clock. Input (stdin): { "workers": n, "gapTimeoutMs": ms, "messages": [{ "at", "key", "seq", "ms" }], "summary"?: true } (at = delivery time, ms = processing time). At each clock time the runner completes the events that finish now, delivers the events that arrive now in input order, calls expireGaps(), then calls take() while a worker is free. It prints a line per finished, dropped and rejected event and per gap, then each key''s processing order and the totals (with summary, only the last two).', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 1, 'For one learner, what has to be true before an event may start - about the event itself and about the learner''s other events? And what may a worker do instead while that learner cannot go on?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 2, 'Keep three things per key: the next expected seq, the events held for it (looked up by seq, plus the order in which they were received), and whether one of its events is in flight. take() looks only at the event whose seq equals the next expected one for each idle key - never at a single shared queue head. For the gap timer, re-check the key after every receive and every take: lowest held seq > next expected means a gap; remember the time only when the gap starts.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 3, 'A similar run with gapTimeoutMs 300 and one worker: a#1 arrives at t=0 (100 ms), a#3 at t=10, b#1 at t=20. t=0 a#1 starts. t=10 a#3 is held; a expects 2 and its lowest held seq is 3, so a gap starts at t=10 (deadline t=310). t=100 a#1 ends; a#2 is missing, so the free worker takes b#1 (t=100-200). t=310 the gap expires: report { a, from 2, to 2 }, a now expects 3, a#3 runs t=310-410. If a#2 then arrives, it is dropped.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
