VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 'The incident: u_17#3 arrives before #2 and waits; u_42 keeps going', '{"workers":2,"gapTimeoutMs":2000,"messages":[{"at":0,"key":"u_17","seq":1,"ms":300},{"at":0,"key":"u_42","seq":1,"ms":200},{"at":50,"key":"u_17","seq":3,"ms":100},{"at":120,"key":"u_42","seq":2,"ms":200},{"at":400,"key":"u_17","seq":2,"ms":150},{"at":450,"key":"u_42","seq":3,"ms":100}]}', '"t=200 u_42#1 done (started 0)\nt=300 u_17#1 done (started 0)\nt=400 u_42#2 done (started 200)\nt=550 u_17#2 done (started 400)\nt=550 u_42#3 done (started 450)\nt=650 u_17#3 done (started 550)\nu_17: 1 2 3\nu_42: 1 2 3\nprocessed 6, dropped 0, rejected 0, gaps 0, finished at t=650"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 'A lost event: the gap times out, later events go on, the late copy is dropped', '{"workers":2,"gapTimeoutMs":1000,"messages":[{"at":0,"key":"u_17","seq":1,"ms":100},{"at":10,"key":"u_17","seq":2,"ms":100},{"at":20,"key":"u_17","seq":5,"ms":100},{"at":30,"key":"u_17","seq":3,"ms":100},{"at":40,"key":"u_42","seq":1,"ms":100},{"at":60,"key":"u_17","seq":6,"ms":100},{"at":1500,"key":"u_17","seq":4,"ms":100},{"at":1600,"key":"u_42","seq":2,"ms":100}]}', '"t=100 u_17#1 done (started 0)\nt=140 u_42#1 done (started 40)\nt=200 u_17#2 done (started 100)\nt=300 u_17#3 done (started 200)\nt=1200 gap u_17: gave up waiting for #4\nt=1300 u_17#5 done (started 1200)\nt=1400 u_17#6 done (started 1300)\nt=1500 u_17#4 dropped\nt=1700 u_42#2 done (started 1600)\nu_17: 1 2 3 5 6 | skipped #4\nu_42: 1 2\nprocessed 7, dropped 1, rejected 0, gaps 1, finished at t=1700"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 'No head-of-line blocking: a slow key and a key waiting for a gap do not stop others', '{"workers":3,"gapTimeoutMs":5000,"messages":[{"at":0,"key":"u_7","seq":1,"ms":4000},{"at":0,"key":"u_17","seq":2,"ms":100},{"at":10,"key":"u_7","seq":2,"ms":4000},{"at":20,"key":"u_42","seq":1,"ms":100},{"at":30,"key":"u_42","seq":2,"ms":100},{"at":40,"key":"u_42","seq":3,"ms":100},{"at":50,"key":"u_99","seq":1,"ms":100},{"at":3000,"key":"u_17","seq":1,"ms":100}]}', '"t=120 u_42#1 done (started 20)\nt=150 u_99#1 done (started 50)\nt=220 u_42#2 done (started 120)\nt=320 u_42#3 done (started 220)\nt=3100 u_17#1 done (started 3000)\nt=3200 u_17#2 done (started 3100)\nt=4000 u_7#1 done (started 0)\nt=8000 u_7#2 done (started 4000)\nu_17: 1 2\nu_42: 1 2 3\nu_7: 1 2\nu_99: 1\nprocessed 8, dropped 0, rejected 0, gaps 0, finished at t=8000"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 'Duplicates of a processed, an in-flight and a held event are dropped', '{"workers":2,"gapTimeoutMs":1000,"messages":[{"at":0,"key":"u_17","seq":1,"ms":500},{"at":100,"key":"u_17","seq":1,"ms":500},{"at":150,"key":"u_17","seq":3,"ms":100},{"at":160,"key":"u_17","seq":3,"ms":100},{"at":200,"key":"u_17","seq":2,"ms":200},{"at":300,"key":"u_42","seq":1,"ms":100},{"at":450,"key":"u_42","seq":1,"ms":100},{"at":900,"key":"u_17","seq":1,"ms":500},{"at":1200,"key":"u_17","seq":2,"ms":200}]}', '"t=100 u_17#1 dropped\nt=160 u_17#3 dropped\nt=400 u_42#1 done (started 300)\nt=450 u_42#1 dropped\nt=500 u_17#1 done (started 0)\nt=700 u_17#2 done (started 500)\nt=800 u_17#3 done (started 700)\nt=900 u_17#1 dropped\nt=1200 u_17#2 dropped\nu_17: 1 2 3\nu_42: 1\nprocessed 4, dropped 5, rejected 0, gaps 0, finished at t=800"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 'Gap timer edges: filled at the deadline, expired 1 ms before, counted while the key is busy', '{"workers":1,"gapTimeoutMs":500,"messages":[{"at":0,"key":"u_17","seq":2,"ms":100},{"at":500,"key":"u_17","seq":1,"ms":100},{"at":1000,"key":"u_42","seq":2,"ms":100},{"at":1501,"key":"u_42","seq":1,"ms":100},{"at":2000,"key":"u_7","seq":1,"ms":1000},{"at":2100,"key":"u_7","seq":3,"ms":100},{"at":2700,"key":"u_7","seq":2,"ms":100}]}', '"t=600 u_17#1 done (started 500)\nt=700 u_17#2 done (started 600)\nt=1500 gap u_42: gave up waiting for #1\nt=1501 u_42#1 dropped\nt=1600 u_42#2 done (started 1500)\nt=2600 gap u_7: gave up waiting for #2\nt=2700 u_7#2 dropped\nt=3000 u_7#1 done (started 2000)\nt=3100 u_7#3 done (started 3000)\nu_17: 1 2\nu_42: 2 | skipped #1\nu_7: 1 3 | skipped #2\nprocessed 5, dropped 2, rejected 0, gaps 2, finished at t=3100"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_312'), 'Invalid events go to the dead-letter queue and change nothing', '{"workers":2,"gapTimeoutMs":1000,"messages":[{"at":0,"key":"u_17","seq":1,"ms":100},{"at":10,"key":"","seq":2,"ms":100},{"at":20,"key":"u_17","seq":0,"ms":100},{"at":30,"key":"u_17","seq":"2","ms":100},{"at":40,"key":"u_17","seq":2.5,"ms":100},{"at":50,"key":42,"seq":1,"ms":100},{"at":60,"seq":3,"ms":100},{"at":70,"key":"u_17","seq":2,"ms":100},{"at":80,"key":"u_42","seq":1,"ms":100}]}', '"t=10 rejected {\"at\":10,\"key\":\"\",\"seq\":2,\"ms\":100}\nt=20 rejected {\"at\":20,\"key\":\"u_17\",\"seq\":0,\"ms\":100}\nt=30 rejected {\"at\":30,\"key\":\"u_17\",\"seq\":\"2\",\"ms\":100}\nt=40 rejected {\"at\":40,\"key\":\"u_17\",\"seq\":2.5,\"ms\":100}\nt=50 rejected {\"at\":50,\"key\":42,\"seq\":1,\"ms\":100}\nt=60 rejected {\"at\":60,\"seq\":3,\"ms\":100}\nt=100 u_17#1 done (started 0)\nt=180 u_42#1 done (started 80)\nt=200 u_17#2 done (started 100)\nu_17: 1 2\nu_42: 1\nprocessed 3, dropped 0, rejected 6, gaps 0, finished at t=200"', 2, false, true, 6),
