-- challenge chal_quiz_dce_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dce_321', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-3-2' AND is_deleted = false LIMIT 1), 'safe-replay-quiz', 'Read the replay evidence: skipped, doubled or behind?', 'Two pieces of evidence from the leaderboard projection: a handler that crashed between two statements, and the offsets of a rebuilt version before the switch.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_321'), 'The leaderboard handler after the first fix (each db.query runs in autocommit mode, no BEGIN):

const { rows } = await db.query(
  "SELECT last_offset FROM projection_offsets WHERE projection = ''leaderboard'' AND partition = $1", [partition]);
if (rows.length && offset <= rows[0].last_offset) return;            // already applied
await db.query("UPDATE leaderboard SET score = score + $1 WHERE learner_id = $2", [points, learnerId]);
await db.query("UPDATE projection_offsets SET last_offset = $1 WHERE projection = ''leaderboard'' AND partition = $2", [offset, partition]);

Pod log:
14:02:07.204 apply p3 offset=51877 u_17 +50
14:02:07.209 OOMKilled (exit 137)
14:02:19.630 started, consumer group resumes p3 at offset 51870
14:02:19.702 apply p3 offset=51877 u_17 +50

Statement: "Because the handler skips offsets at or below projection_offsets.last_offset, the second delivery of offset 51877 cannot add u_17''s 50 points again."', 'single_choice'::question_type, 'False. The skip only works if the stored offset always describes the stored score. Here they are written by two autocommit statements: the pod was killed after the score UPDATE committed and before the offset UPDATE ran, so last_offset is still below 51877 and the redelivery passes the check and adds 50 points a second time. Put the offset check, the score change and the offset change in one transaction (BEGIN ... COMMIT), so a crash leaves either both or neither. The misconception is that having an offset check is enough; what makes it safe is that the offset is committed atomically with the state it protects.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_321'), 'leaderboard_v2 is being rebuilt from offset 0 while leaderboard_v1 keeps serving and consuming live events. Before switching the leaderboard view to v2, the on-call engineer runs:

SELECT partition, projection, last_offset FROM projection_offsets ORDER BY partition, projection;

 partition | projection     | last_offset
-----------+----------------+------------
         0 | leaderboard_v1 |       88120
         0 | leaderboard_v2 |       88123
         1 | leaderboard_v1 |       90417
         1 | leaderboard_v2 |       90410
         2 | leaderboard_v1 |       71002
         2 | leaderboard_v2 |       71002

Statement: "Switching readers to leaderboard_v2 right now could show some learners fewer points than v1 shows them."', 'single_choice'::question_type, 'True. v2 is ahead on partition 0 and level on partition 2, but behind on partition 1: offsets 90411 to 90417 are already in v1 and not yet in v2. Learners whose events are in that range would lose points the moment readers switch. A version has caught up only when, for every partition, its last applied offset is at least the active version''s; partitions are independent, so being ahead on one does not make up for being behind on another. Wait (or run the check in a loop) until the query that lists partitions where v2 is behind returns no rows, then switch in the same transaction as that check.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_dce_322 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dce_322', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-3-2' AND is_deleted = false LIMIT 1), 'safe-replay-projection', 'Replay into the leaderboard without doubling a score', 'Replaying three days of points events into the CodeDev leaderboard doubled every score in that range, because the projection added points for every delivery. Write LeaderboardStore, a leaderboard read model kept in versions ("v1", "v2", ...) that counts every event at most once per version, whether it comes from the live consumer, a replay from an offset, a full rebuild or a redelivery after a crash. Events are { p, o, learner, points }: partition, offset inside that partition (offsets of different partitions are unrelated), learner id, points (may be negative). All state lives in the provided FakeDb (tx(fn) commits fn''s writes atomically, or nothing if fn throws): after a crash the runner creates a new LeaderboardStore on the same database. apply(version, event) returns "rejected" without a transaction when p or o is not an integer >= 0, learner is not a non-empty string or points is not an integer; otherwise it makes exactly one db.tx call, reads the last applied offset of (version, p) inside it, returns "skipped" and writes nothing when o is at or below it, else adds points to the learner''s score in that version and stores o as the last applied offset of (version, p) in the same transaction and returns "applied". switchTo(version) makes version the active one in one transaction only if it has caught up: for every partition the active version has applied, the target''s last applied offset exists and is at least as high; it returns true (switched, or already active) or false (nothing changes). active() returns the active version ("v1" at first); scores(version) and offsets(version) return { learner: score } and { "<partition>": last offset } ({} when empty). Input (stdin): { "log": [events in broker order], "ops": [...] } with ops { op: "live", n, crashAt? } (the live consumer applies its next n events to the active version and then commits its position; with crashAt { p, o } the process crashes right after the first commit made while applying that event, and the consumer restarts from its last committed position), { op: "replay", version, p, from } (every event of partition p with offset >= from, from the whole log), { op: "rebuild", version, n? } (the next n events of the log, or the rest, into that version), { op: "switch", to }. The runner prints one line per op, then the active version and each version''s offsets, number of learners, total and top 3.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 1, 'Picture the process dying a microsecond after a commit. What must already be true in the database for the redelivered event to be recognised - and what would happen if the score were saved but the offset that explains it were not?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 2, 'Look at three things: the key of a stored offset (it must name both the version and the partition), where the offset check happens (inside the same db.tx call as the writes, not in a transaction before it, and not in a field of the class that disappears on restart), and the comparison (an offset equal to the stored one has already been applied). For switchTo, walk the active version''s offsets and compare each partition with the target''s, in one transaction with the write of the new active version.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 3, 'A similar run on a different log: v1 has applied p0 up to 7 and p1 up to 3. A replay of p1 from 0 delivers p1#0..p1#5: #0-#3 are skipped, #4 and #5 are applied, and v1''s p1 becomes 5. A rebuild of v2 that has reached p0=9 and p1=2 cannot replace v1 yet (p1: 2 < 5), even though it is ahead on p0; after it reaches p1=5 the switch succeeds, and the live events that v2 already has are then skipped by v2.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 'The incident: replaying both partitions from an old offset changes no score', '{"log":[{"p":0,"o":0,"learner":"u_17","points":50},{"p":1,"o":0,"learner":"u_42","points":20},{"p":0,"o":1,"learner":"u_42","points":10},{"p":0,"o":2,"learner":"u_17","points":20},{"p":1,"o":1,"learner":"u_7","points":50},{"p":1,"o":2,"learner":"u_17","points":10},{"p":0,"o":3,"learner":"u_7","points":20},{"p":1,"o":3,"learner":"u_42","points":50}],"ops":[{"op":"live","n":8},{"op":"replay","version":"v1","p":0,"from":0},{"op":"replay","version":"v1","p":1,"from":2}]}', '"live 8: applied 8, skipped 0, rejected 0 -> position 8/8\nreplay v1 p0 from 0: applied 0, skipped 4, rejected 0\nreplay v1 p1 from 2: applied 0, skipped 2, rejected 0\nactive v1\nv1: offsets p0=3 p1=3; learners 3, total 230; top u_17=80 u_42=80 u_7=70"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 'Rebuild into v2, switch refused while behind, switch once caught up, live goes on in v2', '{"log":[{"p":0,"o":0,"learner":"u_17","points":50},{"p":1,"o":0,"learner":"u_42","points":20},{"p":0,"o":1,"learner":"u_42","points":10},{"p":0,"o":2,"learner":"u_17","points":20},{"p":1,"o":1,"learner":"u_7","points":50},{"p":1,"o":2,"learner":"u_17","points":10},{"p":0,"o":3,"learner":"u_7","points":20},{"p":1,"o":3,"learner":"u_42","points":50},{"p":0,"o":4,"learner":"u_7","points":10},{"p":1,"o":4,"learner":"u_17","points":20}],"ops":[{"op":"live","n":6},{"op":"rebuild","version":"v2","n":4},{"op":"switch","to":"v2"},{"op":"rebuild","version":"v2"},{"op":"switch","to":"v2"},{"op":"live","n":10}]}', '"live 6: applied 6, skipped 0, rejected 0 -> position 6/10\nrebuild v2: applied 4, skipped 0, rejected 0 -> position 4/10\nswitch to v2: refused, active stays v1\nrebuild v2: applied 6, skipped 0, rejected 0 -> position 10/10\nswitch to v2: ok\nlive 10: applied 0, skipped 4, rejected 0 -> position 10/10\nactive v2\nv1: offsets p0=2 p1=2; learners 3, total 160; top u_17=80 u_7=50 u_42=30\nv2: offsets p0=4 p1=4; learners 3, total 260; top u_17=100 u_42=80 u_7=80"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 'Crash right after a commit: the redelivered events are skipped, nothing counts twice', '{"log":[{"p":0,"o":0,"learner":"u_17","points":50},{"p":1,"o":0,"learner":"u_42","points":20},{"p":0,"o":1,"learner":"u_42","points":10},{"p":0,"o":2,"learner":"u_17","points":20},{"p":1,"o":1,"learner":"u_7","points":50},{"p":1,"o":2,"learner":"u_17","points":10},{"p":0,"o":3,"learner":"u_7","points":20},{"p":1,"o":3,"learner":"u_42","points":50},{"p":0,"o":4,"learner":"u_7","points":10},{"p":1,"o":4,"learner":"u_17","points":20}],"ops":[{"op":"live","n":3},{"op":"live","n":4,"crashAt":{"p":0,"o":2}},{"op":"live","n":4,"crashAt":{"p":1,"o":2}},{"op":"live","n":10}]}', '"live 3: applied 3, skipped 0, rejected 0 -> position 3/10\nlive 4: applied 0, skipped 0, rejected 0; crash after a commit while applying p0#2, restart from position 3\nlive 4: applied 1, skipped 1, rejected 0; crash after a commit while applying p1#2, restart from position 3\nlive 10: applied 4, skipped 3, rejected 0 -> position 10/10\nactive v1\nv1: offsets p0=4 p1=4; learners 3, total 260; top u_17=100 u_42=80 u_7=80"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 'Offsets are per partition: p1 at offset 3 is new even though p0 is past 100', '{"log":[{"p":0,"o":100,"learner":"u_17","points":10},{"p":1,"o":3,"learner":"u_42","points":20},{"p":0,"o":101,"learner":"u_42","points":10},{"p":1,"o":4,"learner":"u_17","points":50},{"p":2,"o":0,"learner":"u_7","points":5},{"p":1,"o":5,"learner":"u_7","points":10},{"p":0,"o":102,"learner":"u_17","points":20}],"ops":[{"op":"live","n":7},{"op":"replay","version":"v1","p":1,"from":0}]}', '"live 7: applied 7, skipped 0, rejected 0 -> position 7/7\nreplay v1 p1 from 0: applied 0, skipped 3, rejected 0\nactive v1\nv1: offsets p0=102 p1=5 p2=0; learners 3, total 125; top u_17=80 u_42=30 u_7=15"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 'A replay that runs ahead of the live consumer, then live and a redelivered last event', '{"log":[{"p":0,"o":0,"learner":"u_17","points":50},{"p":1,"o":0,"learner":"u_42","points":20},{"p":0,"o":1,"learner":"u_42","points":10},{"p":0,"o":2,"learner":"u_17","points":20},{"p":1,"o":1,"learner":"u_7","points":50},{"p":1,"o":2,"learner":"u_17","points":10},{"p":0,"o":3,"learner":"u_7","points":20},{"p":1,"o":3,"learner":"u_42","points":50},{"p":0,"o":4,"learner":"u_7","points":10},{"p":1,"o":4,"learner":"u_17","points":20},{"p":1,"o":4,"learner":"u_17","points":20}],"ops":[{"op":"live","n":3},{"op":"replay","version":"v1","p":0,"from":0},{"op":"live","n":5},{"op":"replay","version":"v1","p":1,"from":3},{"op":"live","n":10}]}', '"live 3: applied 3, skipped 0, rejected 0 -> position 3/11\nreplay v1 p0 from 0: applied 3, skipped 2, rejected 0\nlive 5: applied 3, skipped 2, rejected 0 -> position 8/11\nreplay v1 p1 from 3: applied 1, skipped 2, rejected 0\nlive 10: applied 0, skipped 3, rejected 0 -> position 11/11\nactive v1\nv1: offsets p0=4 p1=4; learners 3, total 260; top u_17=100 u_42=80 u_7=80"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 'Each version keeps its own offsets; switching to an empty version or the same one', '{"log":[{"p":0,"o":0,"learner":"u_17","points":50},{"p":1,"o":0,"learner":"u_42","points":20},{"p":0,"o":1,"learner":"u_42","points":10},{"p":0,"o":2,"learner":"u_17","points":20},{"p":1,"o":1,"learner":"u_7","points":50},{"p":1,"o":2,"learner":"u_17","points":10},{"p":0,"o":3,"learner":"u_7","points":20},{"p":1,"o":3,"learner":"u_42","points":50}],"ops":[{"op":"live","n":8},{"op":"switch","to":"v3"},{"op":"switch","to":"v1"},{"op":"rebuild","version":"v2"},{"op":"switch","to":"v2"},{"op":"replay","version":"v1","p":0,"from":2},{"op":"switch","to":"v1"}]}', '"live 8: applied 8, skipped 0, rejected 0 -> position 8/8\nswitch to v3: refused, active stays v1\nswitch to v1: ok\nrebuild v2: applied 8, skipped 0, rejected 0 -> position 8/8\nswitch to v2: ok\nreplay v1 p0 from 2: applied 0, skipped 2, rejected 0\nswitch to v1: ok\nactive v1\nv1: offsets p0=3 p1=3; learners 3, total 230; top u_17=80 u_42=80 u_7=70\nv2: offsets p0=3 p1=3; learners 3, total 230; top u_17=80 u_42=80 u_7=70\nv3: offsets none; learners 0, total 0; top none"', 3, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 'Invalid events are rejected without a write; revoked (negative) points are applied', '{"log":[{"p":0,"o":0,"learner":"u_17","points":50},{"p":0,"o":-1,"learner":"u_17","points":10},{"p":0,"o":"1","learner":"u_17","points":10},{"p":0,"o":1,"learner":"","points":10},{"p":0,"o":1,"learner":"u_17","points":2.5},{"p":0,"o":1,"learner":"u_17","points":"10"},{"p":-1,"o":1,"learner":"u_17","points":10},{"p":1,"o":0,"points":10},{"p":0,"o":1,"learner":"u_17","points":-20},{"p":1,"o":0,"learner":"u_42","points":30}],"ops":[{"op":"live","n":10},{"op":"replay","version":"v1","p":0,"from":0}]}', '"live 10: applied 3, skipped 0, rejected 7 -> position 10/10\nreplay v1 p0 from 0: applied 0, skipped 2, rejected 4\nactive v1\nv1: offsets p0=1 p1=0; learners 2, total 60; top u_17=30 u_42=30"', 2, false, true, 7),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_322'), 'Large: 1100+ events on 4 partitions, a crash, a replay, a rebuild and a switch', '{"log":[{"p":1,"o":120,"learner":"u_1029","points":20},{"p":1,"o":121,"learner":"u_1008","points":10},{"p":3,"o":77777,"learner":"u_1014","points":10},{"p":2,"o":0,"learner":"u_1001","points":20},{"p":0,"o":5000,"learner":"u_1046","points":10},{"p":2,"o":1,"learner":"u_1058","points":5},{"p":2,"o":2,"learner":"u_1058","points":20},{"p":3,"o":77778,"learner":"u_1025","points":10},{"p":0,"o":5001,"learner":"u_1032","points":5},{"p":3,"o":77779,"learner":"u_1055","points":5},{"p":0,"o":5002,"learner":"u_1001","points":5},{"p":0,"o":5003,"learner":"u_1012","points":10},{"p":1,"o":122,"learner":"u_1044","points":-10},{"p":3,"o":77780,"learner":"u_1013","points":20},{"p":0,"o":5004,"learner":"u_1002","points":50},{"p":3,"o":77781,"learner":"u_1012","points":20},{"p":2,"o":3,"learner":"u_1015","points":50},{"p":2,"o":4,"learner":"u_1041","points":-10},{"p":2,"o":5,"learner":"u_1015","points":-10},{"p":3,"o":77782,"learner":"u_1046","points":50},{"p":0,"o":5005,"learner":"u_1019","points":20},{"p":3,"o":77783,"learner":"u_1013","points":20},{"p":3,"o":77784,"learner":"u_1057","points":50},{"p":3,"o":77785,"learner":"u_1028","points":10},{"p":1,"o":123,"learner":"u_1047","points":20},{"p":2,"o":6,"learner":"u_1024","points":50},{"p":1,"o":124,"learner":"u_1027","points":5},{"p":2,"o":7,"learner":"u_1052","points":10},{"p":0,"o":5006,"learner":"u_1022","points":10},{"p":3,"o":77786,"learner":"u_1024","points":10},{"p":2,"o":8,"learner":"u_1054","points":5},{"p":3,"o":77787,"learner":"u_1009","points":5},{"p":3,"o":77788,"learner":"u_1040","points":50},{"p":2,"o":9,"learner":"u_1054","points":20},{"p":1,"o":125,"learner":"u_1000","points":5},{"p":2,"o":10,"learner":"u_1028","points":5},{"p":2,"o":11,"learner":"u_1020","points":10},{"p":2,"o":12,"learner":"u_1018","points":5},{"p":3,"o":77789,"learner":"u_1027"