-- challenge chal_quiz_dce_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dce_331', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-3-3' AND is_deleted = false LIMIT 1), 'eventual-consistency-quiz', 'Lag, read-your-writes and the data that must not lag', 'Three pieces of evidence from CodeDev: a consumer-lag dashboard, a double-click on Enroll, and a time-based fix for a stale profile.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_331');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_331');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_331'), 'The certificates dashboard at 14:05:

kafka consumer lag   group=certificates  topic=enrollment-events   total lag = 0
outbox_pending       SELECT count(*) FROM outbox WHERE published_at IS NULL  ->  1 840
outbox_oldest_age    now() - min(created_at) WHERE published_at IS NULL     ->  00:06:12
certificates DLQ     messages in the last hour                              ->  3

Statement: "Since the certificate consumer''s lag is 0, every learner who completed a course before 14:05 can already see their certificate."', 'single_choice'::question_type, 'False. Consumer lag only measures the distance between the newest message in the topic and the consumer''s position. The 1 840 enrollment events still waiting in the outbox (the oldest for over 6 minutes) have not reached the topic yet, so the consumer cannot lag behind them; and the 3 messages in the dead-letter queue were consumed but never turned into certificates. Staleness has to be measured end to end - from the source fact (enrollments.completed_at) to the visible result (certificates.issued_at) - plus each hop''s own lag. The misconception is that a lag of 0 on one hop means the whole pipeline has converged.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_331') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_331'), 'EnrollmentsService.enroll() before charging the card:

const existing = await this.search.findEnrollment(learnerId, courseId);  // course-search index, fed by enrollment events, lag 1-5 s
if (existing) throw new ConflictException("ALREADY_ENROLLED");
await this.payments.charge(learnerId, price);
await this.db.query("INSERT INTO enrollments (learner_id, course_id) VALUES ($1, $2)", [learnerId, courseId]);

API log:
09:14:02.120 POST /enrollments u_17 course=postgres-performance
09:14:02.410 POST /enrollments u_17 course=postgres-performance
09:14:03.900 payments: charged u_17 349000 (pay_7741)
09:14:04.050 payments: charged u_17 349000 (pay_7742)

Statement: "Making the search index update faster would make this rarer but not impossible; the check has to be decided by the enrollments table itself, for example with UNIQUE (learner_id, course_id) and inserting a pending enrollment before the charge."', 'single_choice'::question_type, 'True. Any read model fed by events lags by some amount, so a second request inside that window always sees "not enrolled"; here the two requests are 290 ms apart and the index lags seconds. Uniqueness of an enrollment is an invariant that money depends on, so it must be enforced where the write happens: a UNIQUE constraint makes the second INSERT fail, and inserting a pending enrollment first (then charging, then marking it active) means the second request is turned away before a second charge. Read models are fine for showing data, not for deciding invariants. The misconception is that a fast enough read model is as good as a strongly consistent check.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_331') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_331'), 'Learners complained that after renaming themselves the profile page still showed the old name. The fix: after PATCH /me commits on the PostgreSQL primary, the API sets a cookie rw_until = now + 5 s; while it is valid, that learner''s reads go to the primary, otherwise to a read replica.

Replica lag over the last 7 days (now() - pg_last_xact_replay_timestamp() on the replica, sampled every 10 s):
p50 0.08 s   p99 1.2 s   max 9.4 s (14:00 on Monday, during a VACUUM of a large table)

Statement: "With this cookie, a learner who renames themselves will see the new name on the next page load."', 'single_choice'::question_type, 'False. A fixed time window is a guess about replica lag, and the lag reached 9.4 s on Monday: a read sent to the replica 6 s after the write could still return the old name. Read-your-writes needs a comparison, not a timer: return the commit position of the write (for example pg_current_wal_lsn() read right after the commit, kept in the session) and route a read to a replica only if its pg_last_wal_replay_lsn() has reached that position - otherwise read from the primary. The timer is fine as a cheap heuristic only if a stale read after it is acceptable. The misconception is that a window longer than the usual lag guarantees anything about the worst case.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_331') AND order_index = 3)
    RETURNING id
)
