-- challenge chal_quiz_dce_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_dce_421', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-4-2' AND is_deleted = false LIMIT 1), 'reconciliation-quiz', 'Reconciliation: find and fix drift', 'Two statements on the nightly reconciliation of the CodeDev leaderboard: a learner the reconciler deferred, and a week of runs that each ended with zero open differences.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_421');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_421');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_421'), 'Dry-run output of the reconciler, grace period 120 s. The leaderboard projector applies each ProgressRecorded event as an increment (UPDATE leaderboard SET xp = xp + $delta):

reconcile-leaderboard 02:00:00 dry-run
  u_17  source xp=420  read model xp=380  last source change 01:59:58  -> deferred (in flight)

progress outbox 01:59:58 ProgressRecorded u_17 lesson=l_9 xpDelta=+40  published=false

Statement: "Writing xp=420 for u_17 now, instead of deferring, risks giving the learner 460 XP once the projector applies the +40 event that is still in flight."', 'single_choice'::question_type, 'True. The source already includes the +40 (420), and the read model is behind only because the event has not been published and applied yet. If the reconciler sets 420 and the projector then applies its increment, the read model ends at 460: the reconciler and the projector corrected the same gap twice. The grace period skips keys whose source changed recently so the normal pipeline can finish; a later run sees the key settled. The misconception is that a reconciler setting an absolute value can never make things worse; it can whenever it races with an incremental projector.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_421'), 'Hourly reconciliation runs of the leaderboard (cap 500 fixes per run, grace period 300 s):

run    found  applied  over cap  deferred  open after run
09:00    212      212         0         4               0
10:00    198      198         0         6               0
11:00    205      205         0         3               0
12:00    221      221         0         5               0

All differences found are "wrong value"; every one is on a learner who finished a lesson on the mobile app.

Statement: "Every run ends with 0 open differences, so the leaderboard is consistent and the reconciliation can safely move from hourly to daily."', 'single_choice'::question_type, 'False. "0 open after run" only shows that each run applied what it found. About 200 new differences appear every hour, all with one pattern (mobile lessons), which points to a projector bug that keeps creating drift; the reconciler is hiding it. Running it daily would leave up to a day of wrong leaderboard values. Drift found per run is the metric to watch and alert on, and a steady non-zero rate with one pattern is a bug to fix at the source. The misconception is that a reconciler fixes a system; it repairs symptoms and tells you where to look.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_dce_422 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_dce_422', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-4-2' AND is_deleted = false LIMIT 1), 'reconcile-read-models', 'Reconcile the leaderboard and certificates with the source of truth', 'The CodeDev leaderboard (total XP per learner) and the issued certificates are read models built from events, and they drift. Write reconcile(source, model, opts), which compares them with the source of truth (enrollments and progress) and returns the commands that fix them. Expected state: only enrollments with status "active" count. A learner''s expected XP is the sum of the xp of the progress rows of their active enrollments (an active enrollment without a progress row adds 0); every learner with at least one active enrollment must have a leaderboard row, even with 0 XP, and nobody else. A certificate is expected for an active enrollment whose progress has totalLessons > 0 and completedLessons >= totalLessons. Progress rows without an active enrollment are ignored. Differences: an expected certificate that is not in the model: { op: "certificate.issue", userId, courseId }; a certificate in the model that is not expected: { op: "certificate.revoke", userId, courseId }; an expected leaderboard row that is missing: { op: "leaderboard.upsert", userId, xp, was: null }; one with another value: { op: "leaderboard.upsert", userId, xp, was: <model value> }; a leaderboard row that is not expected: { op: "leaderboard.delete", userId, was }. Grace period: a leaderboard command is in flight when any enrollment or progress row of that learner (any course, any status) has now - updatedAt < graceSeconds; a certificate command when the enrollment or progress row of that userId and courseId does; a change exactly graceSeconds old is settled. In-flight commands go to deferred and do not count against the cap. Priority: certificate.issue, then certificate.revoke, then leaderboard.upsert of a missing row, then leaderboard.upsert of a wrong value (larger |xp - was| first), then leaderboard.delete; ties by userId, then courseId, with plain string comparison (< and >). Sort the commands that are not in flight by this priority: the first maxFixes are the fixes, the rest go to skippedByCap; deferred is sorted the same way. Unless opts.dryRun, apply the fixes (and only them) to the model: issue sets certificates["userId:courseId"] = { userId, courseId, issuedAt: now }, revoke deletes it, upsert sets leaderboard[userId] = xp, delete removes it. In a dry run return the same report and change nothing. Options: graceSeconds and maxFixes must be whole numbers >= 0, otherwise return { error: "invalid options" } and change nothing. The runner reads { now, graceSeconds, maxFixes, dryRun, enrollments, progress, leaderboard, certificates }, prints the fixes, the commands over the cap, the deferred ones and a summary as text, then the read model. Do not change the types or the runner.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_422');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_422'), 1, 'Split the job in four parts you can test on their own: what the read models should contain according to the source, which differences exist, which of them are still in flight, and in which order the rest are fixed. Which of these parts needs the clock, and which one is the only part allowed to change the model?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_422'), 2, 'Build the expected state first: a Map from userId to expected XP and a Set of "userId:courseId" keys that deserve a certificate, both from active enrollments only. Then walk both directions for each read model (expected but missing or different, present but not expected). For the grace period, keep the latest updatedAt per learner and per "userId:courseId" over enrollments and progress together. Write one comparator for the priority and use it for both lists.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_422'), 3, 'A similar case on other data, with grace 60 s, cap 1 and now = 1000: a learner has active enrollments in two courses with xp 50 and 30, last change at 900; the leaderboard says 70. A second learner has only a cancelled enrollment (last change at 990) and a leaderboard row of 20. The first gives an upsert xp=80 (wrong value, was 70); the second a delete, but 1000 - 990 = 10 < 60, so it is deferred. With cap 1 the upsert is the one fix; with cap 0 it would go to skippedByCap and the model would stay as it was.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_dce_422'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
