VALUES ('chal_quiz_dce_531', (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'data-consistency-events') AND order_index = 5 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-dce-5-3' AND is_deleted = false LIMIT 1), 'design-review-enrollment-payment-certificate', 'Design review: enrollment, payment & certificate flow', 'Three statements from the review of CodeDev''s payment -> enrollment -> progress -> leaderboard -> certificate flow: the payment webhook''s transaction, a saga that compensated with a refund, and a leaderboard consumer that deduplicated on the wrong id.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_531');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_531');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_531'), 'Payment webhook handler:

await db.tx(async (tx) => {
  const updated = await tx.query(
    "UPDATE payment SET status = ''succeeded'', succeeded_at = now() WHERE provider_payment_id = $1 AND status = ''pending''",
    [event.paymentId],
  );
  if (updated.rowCount === 0) return;   // already handled: the provider retried the webhook
  await tx.query(
    "INSERT INTO outbox (id, event_type, aggregate_id, payload) VALUES ($1, ''PaymentSucceeded'', $2, $3)",
    [ids.next(), event.paymentId, { paymentId: event.paymentId, userId, courseId }],
  );
});
// the process is killed here (OOM), after COMMIT and before the HTTP 200 reaches the provider

Statement: "PaymentSucceeded will still be published, and the enrollment consumer must still be able to handle receiving it more than once."', 'single_choice'::question_type, 'True. The payment update and the outbox row committed together, so the event exists durably and the outbox publisher will publish it after the crash. The provider will retry the webhook because it never got a 200, but the conditional UPDATE finds the row already succeeded and returns before inserting a second outbox row. The enrollment consumer still needs its inbox: the publisher itself publishes at least once, and a crash between publish and mark sends the same row again. The misconception is that the guard against webhook retries makes downstream delivery exactly once; it prevents a second event, not a second delivery of the same event.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_531') AND order_index = 1)
    RETURNING id
)
