WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_531'), 'Enrollment saga log for one purchase:

23:58:10  payments    pay_844 succeeded (outbox: PaymentSucceeded)
23:58:11  email       receipt sent to learner: "Thanks for buying Legacy PHP Basics"
23:58:12  enrollment  step failed permanently: course c_legacy_php is archived
23:58:12  saga        pay_844 -> COMPENSATING, command RefundRequested
23:58:40  payments    pay_844 refunded (provider refund rf_311)
23:58:40  saga        pay_844 -> COMPENSATED

Statement: "Because the saga compensated with a refund, the payment and the failed enrollment behaved like one rolled-back transaction: no other service could have acted on the payment as succeeded."', 'single_choice'::question_type, 'False. A saga has no global transaction: each step commits locally and is visible at once. For 30 seconds the payment was succeeded, and the email service acted on it and sent a receipt the learner has already read. The refund is a new forward action, not an undo, and it can fail on its own. A review therefore asks what users see between the steps (here, perhaps send the receipt only after enrollment, or word it as "processing") and how a failed compensation is retried and alerted. The misconception is that compensation equals rollback; it ends the flow in an accepted state, it does not erase the intermediate one.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_531') AND order_index = 2)
    RETURNING id
)
