WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_531'), 'Leaderboard consumer, inside one transaction with the points-ledger insert:

INSERT INTO inbox (consumer, event_id) VALUES (''leaderboard'', $1) ON CONFLICT DO NOTHING
-- $1 = msg.brokerMessageId

Logs:
10:02:03 outbox-pub   published ob_90017 ProgressRecorded (eventId ob_90017) as broker msg m-5521
10:02:03 outbox-pub   killed before marking ob_90017 published
10:02:04 leaderboard  inbox m-5521 new -> +50 points u_77 lesson 7
10:02:09 outbox-pub   restart; published ob_90017 ProgressRecorded (eventId ob_90017) as broker msg m-5530
10:02:10 leaderboard  inbox m-5530 new -> +50 points u_77 lesson 7

Statement: "Keying the inbox on the eventId carried in the message (ob_90017) instead of the broker message id would have stopped the second +50."', 'single_choice'::question_type, 'True. The publisher crashed between publish and mark, so it published the same outbox row again, and the broker assigned the second copy a new message id. Keyed on m-5521 and m-5530 the inbox sees two different events and both pass. The eventId is written once by the producer into the outbox row and travels unchanged in every copy, so the second insert of ob_90017 would hit the conflict, the transaction would change nothing, and the ledger would hold one +50. The misconception is that any id on the message identifies the event; transport ids such as message ids and offsets identify one delivery, not the business event.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_dce_531') AND order_index = 3)
    RETURNING id
)
